#include <WiFi.h>
#include <WebServer.h>

// ============================================================
// PINS
// ============================================================

const int LDR_PIN = 34;
const int MUSIC_LED_PIN = 27;

// These will be used by the real DFPlayer later
const int DFPLAYER_RX = 16;
const int DFPLAYER_TX = 17;


// ============================================================
// LIGHT DETECTION
// ============================================================

// Wokwi's photoresistor gives LOWER readings when brighter.
//
// Bright enough -> LIGHT ON
// Dark enough   -> LIGHT OFF
//
// The gap between these values prevents flickering.

const int LIGHT_ON_THRESHOLD = 2200;
const int LIGHT_OFF_THRESHOLD = 2500;


// ============================================================
// MUSIC SETTINGS
// ============================================================

const int NUMBER_OF_TRACKS = 10;

int currentTrack = 1;
int defaultTrack = 1;

int volumeLevel = 20;

bool lightIsOn = false;
bool musicIsPlaying = false;


// ============================================================
// WIFI
// ============================================================

const char* ssid = "Wokwi-GUEST";
const char* password = "";

WebServer server(80);


// ============================================================
// SIMULATED DFPPLAYER
// ============================================================
//
// Wokwi cannot actually play DFPlayer MP3 audio.
//
// These functions simulate what the real DFPlayer will do.
// When the real hardware arrives, we replace these functions
// with the actual DFPlayer commands.
// ============================================================


void dfplayerPlay(int track) {

  Serial.println();
  Serial.println("--------------------------------");
  Serial.println("DFPLAYER COMMAND");
  Serial.print("PLAY TRACK: ");
  Serial.println(track);
  Serial.print("VOLUME: ");
  Serial.println(volumeLevel);
  Serial.println("--------------------------------");
  Serial.println();
}


void dfplayerStop() {

  Serial.println();
  Serial.println("--------------------------------");
  Serial.println("DFPLAYER COMMAND");
  Serial.println("STOP");
  Serial.println("--------------------------------");
  Serial.println();
}


void dfplayerNext() {

  Serial.println();
  Serial.println("--------------------------------");
  Serial.println("DFPLAYER COMMAND");
  Serial.println("NEXT TRACK");
  Serial.println("--------------------------------");
  Serial.println();
}


void dfplayerPrevious() {

  Serial.println();
  Serial.println("--------------------------------");
  Serial.println("DFPLAYER COMMAND");
  Serial.println("PREVIOUS TRACK");
  Serial.println("--------------------------------");
  Serial.println();
}


void dfplayerVolume(int volume) {

  Serial.println();
  Serial.println("--------------------------------");
  Serial.print("DFPLAYER COMMAND: VOLUME ");
  Serial.println(volume);
  Serial.println("--------------------------------");
  Serial.println();
}


// ============================================================
// MUSIC CONTROL
// ============================================================


void startMusic() {

  if (!musicIsPlaying) {

    musicIsPlaying = true;

    currentTrack = defaultTrack;

    dfplayerPlay(currentTrack);

    Serial.println("🎵 MUSIC STARTED");
    Serial.print("Playing default track: ");
    Serial.println(currentTrack);

    digitalWrite(MUSIC_LED_PIN, HIGH);
  }
}


void stopMusic() {

  if (musicIsPlaying) {

    musicIsPlaying = false;

    dfplayerStop();

    Serial.println("⏹ MUSIC STOPPED");

    digitalWrite(MUSIC_LED_PIN, LOW);
  }
}


void playCurrentTrack() {

  musicIsPlaying = true;

  dfplayerPlay(currentTrack);

  Serial.print("▶ PLAYING TRACK ");
  Serial.println(currentTrack);

  digitalWrite(MUSIC_LED_PIN, HIGH);
}


void nextTrack() {

  currentTrack++;

  if (currentTrack > NUMBER_OF_TRACKS) {
    currentTrack = 1;
  }

  musicIsPlaying = true;

  dfplayerNext();

  Serial.print("⏭ NEXT TRACK: ");
  Serial.println(currentTrack);

  digitalWrite(MUSIC_LED_PIN, HIGH);
}


void previousTrack() {

  currentTrack--;

  if (currentTrack < 1) {
    currentTrack = NUMBER_OF_TRACKS;
  }

  musicIsPlaying = true;

  dfplayerPrevious();

  Serial.print("⏮ PREVIOUS TRACK: ");
  Serial.println(currentTrack);

  digitalWrite(MUSIC_LED_PIN, HIGH);
}


void playDefault() {

  currentTrack = defaultTrack;

  musicIsPlaying = true;

  dfplayerPlay(currentTrack);

  Serial.print("⭐ DEFAULT TRACK: ");
  Serial.println(currentTrack);

  digitalWrite(MUSIC_LED_PIN, HIGH);
}


void changeVolume(int newVolume) {

  volumeLevel = constrain(newVolume, 0, 30);

  dfplayerVolume(volumeLevel);

  Serial.print("🔊 VOLUME: ");
  Serial.println(volumeLevel);
}


