// ============================================================
// WEB SERVER FUNCTIONS
// ============================================================


void handleRoot() {

  server.send(
    200,
    "text/html",
    webpage()
  );
}


void handlePlay() {

  playCurrentTrack();

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


void handleStop() {

  stopMusic();

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


void handleNext() {

  nextTrack();

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


void handlePrevious() {

  previousTrack();

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


void handleDefault() {

  playDefault();

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


void handleVolume() {

  if (server.hasArg("value")) {

    int newVolume =
      server.arg("value").toInt();

    changeVolume(newVolume);
  }


  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303
  );
}


// ============================================================
// SETUP
// ============================================================


void setup() {

  Serial.begin(115200);

  delay(1000);


  // -------------------------
  // PINS
  // -------------------------

  pinMode(
    LDR_PIN,
    INPUT
  );

  pinMode(
    MUSIC_LED_PIN,
    OUTPUT
  );

  digitalWrite(
    MUSIC_LED_PIN,
    LOW
  );


  // -------------------------
  // ADC
  // -------------------------

  analogReadResolution(12);

  analogSetPinAttenuation(
    LDR_PIN,
    ADC_11db
  );


  // -------------------------
  // STARTUP MESSAGE
  // -------------------------

  Serial.println();

  Serial.println("======================================");

  Serial.println("🚿 BATHROOM MUSIC SYSTEM");

  Serial.println("======================================");

  Serial.println();

  Serial.println("ESP32 starting...");


  // -------------------------
  // WIFI
  // -------------------------

  Serial.println();

  Serial.println("Connecting to WiFi...");


  WiFi.begin(
    ssid,
    password
  );


  while (
    WiFi.status() != WL_CONNECTED
  ) {

    delay(250);

    Serial.print(".");
  }


  Serial.println();

  Serial.println("WiFi connected!");


  Serial.print(
    "ESP32 IP address: "
  );

  Serial.println(
    WiFi.localIP()
  );


  // -------------------------
  // WEB ROUTES
  // -------------------------

  server.on(
    "/",
    handleRoot
  );


  server.on(
    "/play",
    handlePlay
  );


  server.on(
    "/stop",
    handleStop
  );


  server.on(
    "/next",
    handleNext
  );


  server.on(
    "/previous",
    handlePrevious
  );


  server.on(
    "/default",
    handleDefault
  );


  server.on(
    "/volume",
    handleVolume
  );


  server.begin();


  Serial.println();

  Serial.println(
    "🌐 Web server started!"
  );


  Serial.println();

  Serial.println(
    "System ready."
  );

  Serial.println();
}


// ============================================================
// MAIN LOOP
// ============================================================


void loop() {

  // Keep web controller working
  server.handleClient();


  // -------------------------
  // READ LIGHT
  // -------------------------

  int ldrValue =
    analogRead(LDR_PIN);


  // -------------------------
  // LIGHT ON
  // -------------------------

  if (
    !lightIsOn &&
    ldrValue <= LIGHT_ON_THRESHOLD
  ) {

    lightIsOn = true;


    Serial.println();

    Serial.println(
      "💡 LIGHT TURNED ON"
    );


    // Automatically start
    // the default song

    currentTrack =
      defaultTrack;

    startMusic();
  }


  // -------------------------
  // LIGHT OFF
  // -------------------------

  if (
    lightIsOn &&
    ldrValue >= LIGHT_OFF_THRESHOLD
  ) {

    lightIsOn = false;


    Serial.println();

    Serial.println(
      "🌙 LIGHT TURNED OFF"
    );


    stopMusic();
  }


  // -------------------------
  // MUSIC LED
  // -------------------------

  digitalWrite(

    MUSIC_LED_PIN,

    musicIsPlaying
      ? HIGH
      : LOW
  );


  // -------------------------
  // SERIAL DEBUG
  // -------------------------

  Serial.print(
    "LDR: "
  );

  Serial.print(
    ldrValue
  );


  Serial.print(
    " | Light: "
  );

  Serial.print(
    lightIsOn
      ? "ON"
      : "OFF"
  );


  Serial.print(
    " | Music: "
  );

  Serial.print(
    musicIsPlaying
      ? "PLAYING"
      : "STOPPED"
  );


  Serial.print(
    " | Track: "
  );

  Serial.print(
    currentTrack
  );


  Serial.print(
    " | Volume: "
  );

  Serial.println(
    volumeLevel
  );


  delay(500);
}
